};`;

const blogConvexJikanContent = `import { action, query } from "./_generated/server";
import { v } from "convex/values";
import { internal } from "./_generated/api";
import { GoogleGenAI, Type } from "@google/genai";

// --- Actions (Orquestração) ---

/**
 * Gera posts de recomendação de animes.
 */
export const generateContent = action({
  args: {},
  handler: async (ctx) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("ACESSO NEGADO: Usuário não autenticado.");

    // Buscar Animes Populares
    const jikanResponse = await fetch("https://api.jikan.moe/v4/top/anime?limit=3");
    const jikanData = await jikanResponse.json();
    const animes = jikanData.data;

    if (!process.env.GEMINI_API_KEY) throw new Error("FATAL: GEMINI_API_KEY missing.");
    const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });

    let successCount = 0;

    for (const anime of animes) {
        const imageUrl = anime.images?.jpg?.large_image_url || anime.images?.jpg?.image_url;

        // Prompt ajustado: Casual, PT-BR, Sem Jargão Técnico, Recomendação
        const prompt = \`
            Atue como 'Kira', um autor fictício apaixonado por animes deste blog.
            Escreva um post de blog RECOMENDANDO o anime "\${anime.title}".

            Diretrizes:
            - Idioma: Português do Brasil (PT-BR).
            - Tom: Casual, empolgado, jornalístico (estilo revista pop).
            - PROIBIDO: Usar termos técnicos de programação (vibe coding, sistema, algoritmo, etc).
            - Foco: Enredo, personagens e por que vale a pena assistir.

            Saída estrita em JSON:
            {
                "title": "Um título chamativo para o post",
                "content_markdown": "O texto do post em Markdown (use h2, h3, listas)",
                "slug": "slug-amigavel-do-post"
            }
        \`;

        try {
            const response = await ai.models.generateContent({
                model: "gemini-2.5-flash",
                contents: prompt,
                config: {
                    responseMimeType: "application/json",
                    responseSchema: {
                        type: Type.OBJECT,
                        properties: {
                            title: { type: Type.STRING },
                            content_markdown: { type: Type.STRING },
                            slug: { type: Type.STRING }
                        },
                        required: ["title", "content_markdown", "slug"]
                    }
                }
            });

            const data = JSON.parse(response.text!);

            // Chama mutation interna (definida em mutations.ts)
            await ctx.runMutation(internal.mutations.savePost, {
                title: data.title,
                content_markdown: data.content_markdown,
                image_url: imageUrl,
                jikan_id: anime.mal_id,
                slug: data.slug,
                authorId: identity.subject,
                published_date: new Date().toISOString()
            });

            await ctx.runMutation(internal.mutations.logAudit, {
                action: "AI_RECOMMENDATION_POST",
                model: "gemini-2.5-flash",
                input_prompt: \`Recomendar: \${anime.title}\`,
                output_summary: \`Gerado: \${data.title}\`,
                status: "SUCCESS",
                executorId: identity.subject
            });

            successCount++;
            // Pequeno delay para evitar rate limit do Gemini se houver muitos
            await new Promise(resolve => setTimeout(resolve, 1000));

        } catch (err) {
            console.error(err);
            await ctx.runMutation(internal.mutations.logAudit, {
                action: "AI_RECOMMENDATION_POST",
                model: "gemini-2.5-flash",
                input_prompt: \`Recomendar: \${anime.title}\`,
                output_summary: "Falha na geração",
                status: "FAILURE",
                error: (err as Error).message,
                executorId: identity.subject
            });
        }
    }
    return \`SUCESSO: \${successCount} recomendações geradas.\`;
  },
});

/**
 * Gera um time de 3 personagens aleatórios.
 */
export const generateTeam = action({
    args: {},
    handler: async (ctx) => {
        const identity = await ctx.auth.getUserIdentity();
        if (!identity) throw new Error("Auth required");

        const characters = [];

        // Loop 3 vezes para buscar personagens aleatórios
        // Nota: A API Jikan tem rate limit, então usamos um delay.
        for (let i = 0; i < 3; i++) {
            try {
                // Busca personagem aleatório
                const response = await fetch("https://api.jikan.moe/v4/random/characters");
                if (!response.ok) throw new Error("Jikan API Error");
                const data = await response.json();
                const char = data.data;

                const picsResponse = await fetch(\`https://api.jikan.moe/v4/characters/\${char.mal_id}/pictures\`);
                const picsData = await picsResponse.json();

                // Pega a primeira imagem ou fallback para a do perfil principal
                const finalImage = picsData.data?.[0]?.jpg?.image_url || char.images?.jpg?.image_url;

                characters.push({
                    jikanId: char.mal_id,
                    name: char.name,
                    imageUrl: finalImage
                });

                // Delay de 1s para respeitar rate limit da Jikan (aprox 3 req/s)
                await new Promise(r => setTimeout(r, 1200));

            } catch (e) {
                console.error("Erro ao buscar personagem:", e);
                // Fallback para evitar falha total
                characters.push({
                    jikanId: 0,
                    name: "Personagem Desconhecido",
                    imageUrl: "https://placehold.co/200x300?text=Error"
                });
            }
        }

        await ctx.runMutation(internal.mutations.saveTeam, {
            ownerId: identity.subject,
            characters: characters
        });

        return "Time gerado com sucesso!";
    }
});

// --- Queries de Leitura ---

export const getPosts = query({
  handler: async (ctx) => {
    return await ctx.db.query("posts").order("desc").collect();
  },
});

export const getPostBySlug = query({
  args: { slug: v.string() },
  handler: async (ctx, args) => {
    return await ctx.db.query("posts").withIndex("by_slug", q => q.eq("slug", args.slug)).unique();
  },
});

export const getAuditLogs = query({
    handler: async (ctx) => {
        return await ctx.db.query("audit_logs").order("desc").take(10);
    }
});

export const getTeams = query({
    handler: async (ctx) => {
        const identity = await ctx.auth.getUserIdentity();
        if (!identity) return [];
        return await ctx.db
            .query("teams")
            .withIndex("by_owner", q => q.eq("ownerId", identity.subject))
            .order("desc")
            .take(1);
    }
});
`;

const blogAdminDashboardContent = `'use client';
import { useAction, useQuery } from "convex/react";
import { api } from "@/convex/_generated/api";
import { useState } from "react";
import Link from "next/link";
import { SignedIn, SignedOut, RedirectToSignIn } from "@clerk/nextjs";
import TeamCards from "@/components/TeamCards";

const Dashboard = () => {
  const generatePosts = useAction(api.jikan.generateContent);
  const generateTeam = useAction(api.jikan.generateTeam);

  const logs = useQuery(api.jikan.getAuditLogs);
  const posts = useQuery(api.jikan.getPosts);
  const latestTeam = useQuery(api.jikan.getTeams);

  const [isGenPosts, setIsGenPosts] = useState(false);
  const [isGenTeam, setIsGenTeam] = useState(false);
  const [statusMsg, setStatusMsg] = useState("");

  const handleGeneratePosts = async () => {
    setIsGenPosts(true);
    setStatusMsg("Iniciando protocolo de escrita via Gemini...");
    try {
        const result = await generatePosts();
        setStatusMsg(result);
    } catch (e) {
        setStatusMsg(\`Erro: \${(e as Error).message}\`);
    } finally {
        setIsGenPosts(false);
    }
  };

  const handleGenerateTeam = async () => {
    setIsGenTeam(true);
    setStatusMsg("Conectando Jikan API para recrutamento...");
    try {
        await generateTeam();
        setStatusMsg("Novo time recrutado com sucesso.");
    } catch (e) {
        setStatusMsg(\`Erro no recrutamento: \${(e as Error).message}\`);
    } finally {
        setIsGenTeam(false);
    }
  };

  return (
    <div style={{ paddingTop: '20px' }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px', borderBottom: '1px solid var(--border-color)', paddingBottom: '15px' }}>
        <div>
            <h1 style={{ fontSize: '1.5rem', color: 'var(--text-primary)' }}>Painel de Controle</h1>
            <p style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>/root/admin/dashboard</p>
        </div>
        <Link href="/posts" className="btn">Visualizar Blog</Link>
      </header>

      {/* SEÇÃO 1: HEALTH CHECK */}
      <section className="card" style={{ marginBottom: '25px' }}>
        <h2 style={{ fontSize: '1rem', color: 'var(--text-secondary)', marginBottom: '15px', textTransform: 'uppercase' }}>System Health</h2>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px' }}>
            <div style={{ textAlign: 'center' }}>
                <p style={{ fontSize: '0.8rem', color: 'var(--text-secondary)' }}>POSTS PUBLICADOS</p>
                <p style={{ fontSize: '1.5rem', fontWeight: 'bold', color: 'var(--text-primary)' }}>
                    {posts ? posts.length : '-'}
                </p>
            </div>
            <div style={{ textAlign: 'center', borderLeft: '1px solid var(--border-color)', borderRight: '1px solid var(--border-color)' }}>
                <p style={{ fontSize: '0.8rem', color: 'var(--text-secondary)' }}>STATUS API GEMINI</p>
                <p style={{ fontSize: '1.5rem', fontWeight: 'bold', color: 'var(--success-color)' }}>
                    ONLINE
                </p>
            </div>
            <div style={{ textAlign: 'center' }}>
                <p style={{ fontSize: '0.8rem', color: 'var(--text-secondary)' }}>STATUS BD CONVEX</p>
                <p style={{ fontSize: '1.5rem', fontWeight: 'bold', color: 'var(--success-color)' }}>
                    CONECTADO
                </p>
            </div>
        </div>
      </section>

      <div style={{ display: 'grid', gridTemplateColumns: '1.5fr 1fr', gap: '25px' }}>

        {/* COLUNA ESQUERDA: OPERAÇÕES */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '25px' }}>

            {/* GERAÇÃO DE POSTS */}
            <div className="card">
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
                    <h2 style={{ fontSize: '1.1rem', margin: 0 }}>Gerador de Conteúdo</h2>
                    <span style={{ fontSize: '0.7rem', background: 'var(--bg-color)', padding: '2px 6px', borderRadius: '4px', border: '1px solid var(--border-color)' }}>GEMINI 2.5</span>
                </div>
                <p style={{ fontSize: '0.9rem', color: 'var(--text-secondary)', marginBottom: '15px' }}>
                    Escreve 3 recomendações baseadas no TOP Animes do momento.
                </p>
                <button onClick={handleGeneratePosts} disabled={isGenPosts} className="btn" style={{ width: '100%' }}>
                    {isGenPosts ? "PROCESSANDO..." : "EXECUTAR PROTOCOLO DE ESCRITA"}
                </button>
                {statusMsg && (
                    <div style={{ marginTop: '15px', padding: '10px', background: 'var(--bg-color)', borderLeft: '2px solid var(--color-accent)', fontSize: '0.85rem' }}>
                        > {statusMsg}
                    </div>
                )}
            </div>

            {/* SEÇÃO 2: GERAÇÃO DE TIME */}
            <div className="card">
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
                    <h2 style={{ fontSize: '1.1rem', margin: 0 }}>Seu Time Jikan</h2>
                    <span style={{ fontSize: '0.7rem', background: 'var(--bg-color)', padding: '2px 6px', borderRadius: '4px', border: '1px solid var(--border-color)' }}>RANDOMIZER</span>
                </div>

                {latestTeam && latestTeam.length > 0 ? (
                    <div style={{ marginBottom: '20px' }}>
                        <p style={{ fontSize: '0.8rem', color: 'var(--text-secondary)' }}>TIME ATUAL:</p>
                        <TeamCards characters={latestTeam[0].characters} />
                    </div>
                ) : (
                    <p style={{ fontSize: '0.9rem', color: 'var(--text-secondary)', marginBottom: '15px' }}>Nenhum time recrutado ainda.</p>
                )}

                <button onClick={handleGenerateTeam} disabled={isGenTeam} className="btn" style={{ width: '100%' }}>
                    {isGenTeam ? "RECRUTANDO..." : "GERAR NOVO TIME"}
                </button>
            </div>

        </div>

        {/* COLUNA DIREITA: SEÇÃO 3 - RASTREABILIDADE (LOGS) */}
        <div className="card" style={{ maxHeight: '600px', overflowY: 'auto' }}>
            <h2 style={{ fontSize: '1rem', color: 'var(--text-secondary)', marginBottom: '15px', textTransform: 'uppercase' }}>Audit Logs</h2>
            {!logs ? (
                <p style={{ fontSize: '0.9rem', color: 'var(--text-secondary)' }}>Carregando...</p>
            ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                    {logs.map((log) => (
                        <div key={log._id} style={{ borderBottom: '1px solid var(--border-color)', paddingBottom: '10px' }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '5px' }}>
                                <span style={{ fontSize: '0.7rem', color: 'var(--text-secondary)' }}>
                                    {new Date(log.timestamp).toLocaleTimeString()}
                                </span>
                                <span style={{ 
                                    fontSize: '0.65rem', 
                                    padding: '2px 5px', 
                                    borderRadius: '3px',
                                    background: log.status === 'SUCCESS' ? 'rgba(138, 255, 138, 0.1)' : 'rgba(255, 138, 138, 0.1)',
                                    color: log.status === 'SUCCESS' ? 'var(--success-color)' : 'var(--error-color)',
                                    border: '1px solid currentColor'
                                }}>
                                    {log.status}
                                </span>
                            </div>
                            <p style={{ fontSize: '0.8rem', fontWeight: 'bold', color: 'var(--text-primary)', marginBottom: '2px' }}>
                                {log.action}
                            </p>
                            <p style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                {log.output_summary}
                            </p>
                        </div>
                    ))}
                </div>
            )}
        </div>

      </div>
    </div>
  );
};

export default function AdminPage() {
    return (
        <>
            <SignedIn>
                <Dashboard />
            </SignedIn>
            <SignedOut>
                <div style={{ textAlign: 'center', marginTop: '15vh' }}>
                    <h2 style={{ color: 'var(--color-accent)', marginBottom: '10px' }}>ACESSO NEGADO</h2>
                    <p style={{ color: 'var(--text-secondary)', marginBottom: '20px' }}>Esta área é restrita a administradores do sistema.</p>
                    <RedirectToSignIn />
                </div>
            </SignedOut>
        </>
    );
}
`;

const blogGlobalsCssContent = `/* 
  DESIGN SYSTEM: REFINED TERMINAL
  Palette: Off-White, Dark Charcoal, Soft Green
*/

:root {
  /* DARK THEME (Default) */
  --bg-color: #1A1A1A;           /* Very Dark Grey, almost Black */
  --card-bg: #242424;            /* Slightly lighter for cards */
  --text-primary: #EAEAEA;       /* Off-White for readability */
  --text-secondary: #A0A0A0;     /* Muted Grey */
  --color-accent: #8AFF8A;       /* Soft Green for interactive elements */
  --border-color: #333333;       /* Subtle border */
  --font-family: 'Courier New', Courier, monospace; /* Monospace enforced */
  --btn-hover: #8AFF8A;
  --btn-hover-text: #1A1A1A;
  --success-color: #8AFF8A;
  --error-color: #FF8A8A;
}

/* LIGHT THEME (Professional/Clean) */
[data-theme='light'] {
  --bg-color: #F0F0F0;
  --card-bg: #FFFFFF;
  --text-primary: #1A1A1A;
  --text-secondary: #555555;
  --color-accent: #2E7D32;       /* Darker Green for contrast on light */
  --border-color: #D1D1D1;
  --btn-hover: #2E7D32;
  --btn-hover-text: #FFFFFF;
  --success-color: #2E7D32;
  --error-color: #C62828;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  transition: background-color 0.3s ease, color 0.3s ease, border-color 0.3s ease;
}

body {
  background-color: var(--bg-color);
  color: var(--text-primary);
  font-family: var(--font-family);
  line-height: 1.6;
  padding: 20px;
  min-height: 100vh;
}

a {
  color: var(--text-primary);
  text-decoration: none;
  border-bottom: 1px solid var(--text-secondary);
}

a:hover {
  color: var(--color-accent);
  border-bottom-color: var(--color-accent);
}

h1, h2, h3, h4 {
  font-weight: normal;
  letter-spacing: -0.5px;
}

/* UI Components */
.container {
  max-width: 1000px;
  margin: 0 auto;
}

.btn {
    background: transparent;
    border: 1px solid var(--color-accent);
    color: var(--color-accent);
    padding: 10px 20px;
    font-family: var(--font-family);
    cursor: pointer;
    text-transform: uppercase;
    font-weight: bold;
    font-size: 0.85rem;
    letter-spacing: 1px;
    border-radius: 4px;
}

.btn:hover:not(:disabled) {
    background: var(--btn-hover);
    color: var(--btn-hover-text);
}

.btn:disabled {
    border-color: var(--border-color);
    color: var(--text-secondary);
    cursor: not-allowed;
    opacity: 0.5;
}

.card {
    background-color: var(--card-bg);
    border: 1px solid var(--border-color);
    padding: 20px;
