const blogAdminDashboardContent = `'use client';
import { useAction, useQuery, useMutation } from "convex/react";
import { api } from "@/convex/_generated/api";
import { useState } from "react";
import Link from "next/link";
import { SignedIn, SignedOut, RedirectToSignIn } from "@clerk/nextjs";
import TeamCards from "@/components/TeamCards";
import { Id } from "@/convex/_generated/dataModel";

const Dashboard = () => {
  const generatePosts = useAction(api.jikan.generateContent);
  const generateTeam = useAction(api.jikan.generateTeam);
  const generateGame = useAction(api.jikan.generateGame);
  const generatePromo = useAction(api.jikan.generatePromoVideo);

  const updatePost = useMutation(api.mutations.updatePostPublic);
  const deletePost = useMutation(api.mutations.deletePostPublic);

  const logs = useQuery(api.jikan.getAuditLogs);
  const posts = useQuery(api.jikan.getPosts);
  const latestTeam = useQuery(api.jikan.getTeams);
  const latestGame = useQuery(api.jikan.getLatestGame);

  const [isGenPosts, setIsGenPosts] = useState(false);
  const [isGenTeam, setIsGenTeam] = useState(false);
  const [isGenGame, setIsGenGame] = useState(false);
  const [isGenPromo, setIsGenPromo] = useState(false);
  const [statusMsg, setStatusMsg] = useState("");

  const [editingPost, setEditingPost] = useState<any>(null);

  const handleGeneratePosts = async () => {
    setIsGenPosts(true);
    setStatusMsg("Iniciando protocolo de escrita via Gemini...");
    try {
        const result = await generatePosts();
        setStatusMsg(result);
    } catch (e) {
        setStatusMsg(\`Erro: \${(e as Error).message}\`);
    } finally {
        setIsGenPosts(false);
    }
  };

  const handleGenerateTeam = async () => {
    setIsGenTeam(true);
    setStatusMsg("Recrutando time...");
    try {
        await generateTeam();
        setStatusMsg("Novo time recrutado.");
    } catch (e) {
        setStatusMsg(\`Erro: \${(e as Error).message}\`);
    } finally {
        setIsGenTeam(false);
    }
  };

  const handleGenerateGame = async () => {
    setIsGenGame(true);
    setStatusMsg("Acessando mainframe FreeToGame...");
    try {
        await generateGame();
        setStatusMsg("Game da semana atualizado.");
    } catch (e) {
        setStatusMsg(\`Erro: \${(e as Error).message}\`);
    } finally {
        setIsGenGame(false);
    }
  };

  const handleGeneratePromo = async () => {
    setIsGenPromo(true);
    setStatusMsg("Buscando trailers recentes (/watch/promos)...");
    try {
        const res = await generatePromo();
        setStatusMsg(res);
    } catch (e) {
        setStatusMsg(\`Erro: \${(e as Error).message}\`);
    } finally {
        setIsGenPromo(false);
    }
  };

  const handleDeletePost = async (id: Id<"posts">) => {
    if (confirm("Confirmar exclusão deste arquivo?")) {
        await deletePost({ id });
        setStatusMsg("Arquivo deletado do sistema.");
    }
  };

  const handleEditPost = (post: any) => {
    setEditingPost(post);
  };

  const saveEdit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingPost) return;
    try {
        await updatePost({
            id: editingPost._id,
            title: editingPost.title,
            slug: editingPost.slug,
            content_markdown: editingPost.content_markdown,
            image_url: editingPost.image_url
        });
        setEditingPost(null);
        setStatusMsg("Registro atualizado com sucesso.");
    } catch (e) {
        setStatusMsg(\`Erro na atualização: \${(e as Error).message}\`);
    }
  };

  return (
    <div style={{ paddingTop: '20px' }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px', borderBottom: '1px solid var(--border-color)', paddingBottom: '15px' }}>
        <div>
            <h1 style={{ fontSize: '1.5rem', color: 'var(--text-primary)' }}>Painel de Controle</h1>
            <p style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>/root/admin/dashboard</p>
        </div>
        <Link href="/posts" className="btn">Visualizar Blog</Link>
      </header>

      <section className="card" style={{ marginBottom: '25px' }}>
        <h2 style={{ fontSize: '1rem', color: 'var(--text-secondary)', marginBottom: '15px', textTransform: 'uppercase' }}>System Health</h2>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px' }}>
            <div style={{ textAlign: 'center' }}>
                <p style={{ fontSize: '0.8rem', color: 'var(--text-secondary)' }}>POSTS</p>
                <p style={{ fontSize: '1.5rem', fontWeight: 'bold', color: 'var(--text-primary)' }}>{posts ? posts.length : '-'}</p>
            </div>
            <div style={{ textAlign: 'center', borderLeft: '1px solid var(--border-color)', borderRight: '1px solid var(--border-color)' }}>
                <p style={{ fontSize: '0.8rem', color: 'var(--text-secondary)' }}>GEMINI API</p>
                <p style={{ fontSize: '1.5rem', fontWeight: 'bold', color: 'var(--success-color)' }}>READY</p>
            </div>
            <div style={{ textAlign: 'center' }}>
                <p style={{ fontSize: '0.8rem', color: 'var(--text-secondary)' }}>GAME DB</p>
                <p style={{ fontSize: '1.5rem', fontWeight: 'bold', color: latestGame ? 'var(--success-color)' : 'var(--text-secondary)' }}>{latestGame ? 'ACTIVE' : 'EMPTY'}</p>
            </div>
        </div>
      </section>

      {statusMsg && (
        <div style={{ padding: '10px', background: 'var(--bg-color)', borderLeft: '2px solid var(--color-accent)', fontSize: '0.85rem', marginBottom: '20px' }}>
            > {statusMsg}
        </div>
      )}

      {/* ADMIN TOOLS GRID */}
      <div style={{ display: 'grid', gridTemplateColumns: '1.5fr 1fr', gap: '25px' }}>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '25px' }}>

            {/* POST MANAGEMENT LIST */}
            <div className="card">
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
                    <h2 style={{ fontSize: '1.1rem', margin: 0 }}>Gerenciamento de Arquivos</h2>
                    <span style={{ fontSize: '0.7rem', background: 'var(--bg-color)', padding: '2px 6px', borderRadius: '4px', border: '1px solid var(--border-color)' }}>CMS v1.0</span>
                </div>

                <div style={{ maxHeight: '300px', overflowY: 'auto' }}>
                    {posts ? posts.map(post => (
                        <div key={post._id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px', borderBottom: '1px solid var(--border-color)' }}>
