                                <span style={{ fontSize: '0.85rem', fontWeight: 'bold' }}>{post.title}</span>
                                <div style={{ fontSize: '0.7rem', color: 'var(--text-secondary)' }}>{new Date(post.published_date).toLocaleDateString()}</div>
                            </div>
                            <div style={{ display: 'flex', gap: '5px' }}>
                                <button onClick={() => handleEditPost(post)} className="btn" style={{ padding: '2px 8px', fontSize: '0.7rem' }}>EDIT</button>
                                <button onClick={() => handleDeletePost(post._id)} className="btn btn-danger" style={{ padding: '2px 8px', fontSize: '0.7rem' }}>DEL</button>
                            </div>
                        </div>
                    )) : <p>Carregando arquivos...</p>}
                </div>
            </div>

            {/* AI GENERATION CONTROLS */}
            <div className="card">
                <h2 style={{ fontSize: '1.1rem', marginBottom: '15px' }}>Protocolos de IA</h2>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
                    <button onClick={handleGeneratePosts} disabled={isGenPosts} className="btn">
                        {isGenPosts ? "PROCESSANDO..." : "GERAR POSTS (AUTO)"}
                    </button>
                    <button onClick={handleGenerateTeam} disabled={isGenTeam} className="btn">
                        {isGenTeam ? "RECRUTANDO..." : "GERAR NOVO TIME"}
                    </button>
                    <button onClick={handleGeneratePromo} disabled={isGenPromo} className="btn">
                        {isGenPromo ? "BUSCANDO..." : "GERAR PROMO VIDEO"}
                    </button>
                    <button onClick={handleGenerateGame} disabled={isGenGame} className="btn">
                        {isGenGame ? "BUSCANDO..." : "ATUALIZAR GAME"}
                    </button>
                </div>
            </div>

            {/* TIME CARD */}
            <div className="card">
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
                    <h2 style={{ fontSize: '1.1rem', margin: 0 }}>Time Atual</h2>
                </div>
                {latestTeam && latestTeam.length > 0 ? (
                    <TeamCards characters={latestTeam[0].characters} />
                ) : (
                    <p style={{ fontSize: '0.9rem', color: 'var(--text-secondary)' }}>Nenhum time recrutado.</p>
                )}
            </div>

        </div>

        {/* LOGS SIDEBAR */}
        <div className="card" style={{ maxHeight: '600px', overflowY: 'auto' }}>
            <h2 style={{ fontSize: '1rem', color: 'var(--text-secondary)', marginBottom: '15px', textTransform: 'uppercase' }}>Audit Logs</h2>
            {!logs ? <p>Loading...</p> : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                    {logs.map((log) => (
                        <div key={log._id} style={{ borderBottom: '1px solid var(--border-color)', paddingBottom: '10px' }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '5px' }}>
                                <span style={{ fontSize: '0.7rem', color: 'var(--text-secondary)' }}>
