                            </div>
                            <p style={{ fontSize: '0.8rem', fontWeight: 'bold', color: 'var(--text-primary)', marginBottom: '2px' }}>{log.action}</p>
                            <p style={{ fontSize: '0.75rem', color: 'var(--text-secondary)' }}>{log.output_summary}</p>
                        </div>
                    ))}
                </div>
            )}
        </div>

      </div>

      {/* EDIT MODAL */}
      {editingPost && (
        <div style={{
            position: 'fixed', top: 0, left: 0, width: '100%', height: '100%',
            background: 'rgba(0,0,0,0.8)', zIndex: 9999, display: 'flex', alignItems: 'center', justifyContent: 'center'
        }}>
            <div className="card" style={{ width: '90%', maxWidth: '600px', maxHeight: '90vh', overflowY: 'auto', border: '1px solid var(--color-accent)' }}>
                <h2 style={{ marginBottom: '20px', color: 'var(--color-accent)' }}>EDITAR ARQUIVO</h2>
