const blogVibeMatcherComponent = `'use client';
import { useState } from 'react';
import { useAction } from 'convex/react';
import { api } from '@/convex/_generated/api';

export default function VibeMatcher() {
    const matchVibe = useAction(api.jikan.matchVibe);
    const [vibe, setVibe] = useState("");
    const [result, setResult] = useState<any>(null);
    const [loading, setLoading] = useState(false);

    const handleSearch = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!vibe) return;
        setLoading(true);
        try {
            const data = await matchVibe({ vibe });
            setResult(data);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="card" style={{ borderColor: 'var(--color-accent)' }}>
            <h3 style={{ color: 'var(--color-accent)', marginBottom: '10px' }}>VIBE_MATCHER_V1</h3>
            <p style={{ fontSize: '0.9rem', marginBottom: '15px' }}>Digite como você está se sentindo e a IA recomendará um anime.</p>

            <form onSubmit={handleSearch} style={{ display: 'flex', gap: '10px', marginBottom: '20px' }}>
                <input 
                    value={vibe} 
                    onChange={e => setVibe(e.target.value)} 
                    placeholder="Ex: Melancólico num dia chuvoso..."
                    style={{ flex: 1, background: 'var(--bg-color)', border: '1px solid var(--border-color)', color: 'white', padding: '8px' }}
                />
                <button type="submit" className="btn" disabled={loading}>
                    {loading ? "Processando..." : "SCAN"}
                </button>
            </form>

            {result && (
                <div>
                    <p style={{ fontSize: '0.8rem', color: 'var(--text-secondary)' }}>KEYWORD_DETECTED: [{result.keyword}]</p>
                    <ul style={{ marginTop: '10px', paddingLeft: '20px' }}>
                        {result.animes.slice(0, 3).map((anime: any) => (
                            <li key={anime.mal_id} style={{ marginBottom: '5px' }}>
