      })
    ),
    createdAt: v.number(),
  }).index("by_owner", ["ownerId"]),

  games: defineTable({
    title: v.string(),
    thumbnail: v.string(),
    platform: v.string(),
    short_description: v.string(),
    gemini_recommendation: v.string(),
