    'convex/gemini.ts': `import { action } from "./_generated/server";
import { v } from "convex/values";
import { GoogleGenAI, Modality } from "@google/genai";

export const generateWelcomeMessage = action({
  args: { userName: v.string() },
  handler: async (ctx, { userName }) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) return { text: "ACCESS_DENIED", audio: null };
    if (!process.env.GEMINI_API_KEY) return { text: "ERROR: API_KEY missing", audio: null };

    const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });

    // Step 1: Generate Text
    const textPrompt = \`
      You are a system interface (Cyberpunk theme). User: "\${userName}".
      Generate a super short welcome message (max 15 words) in Brazilian Portuguese (PT-BR).
      Example: "Sistema online. Bem-vindo, [User]. Acesso liberado."
    \`;

    let text = "Sistema Online. Bem-vindo.";
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: textPrompt,
        });
        text = response.text || text;
    } catch (e) {
        console.error("Text gen failed", e);
    }

    // Step 2: Generate Audio (TTS)
    // Using the specific TTS model
    let audioData = null;
    try {
        const audioResponse = await ai.models.generateContent({
            model: 'gemini-2.5-flash-preview-tts',
            contents: \`Fale exatamente o seguinte texto em Português do Brasil: \${text}\`,
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Fenrir' } }
                }
            }
        });
        audioData = audioResponse.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    } catch (e) {
        console.error("Audio gen failed", e);
    }

    return { text, audioData };
