    slug: v.string(),             // URL amigável
    authorId: v.string(),         // Clerk ID do autor
    published_date: v.string(),
  }).index("by_slug", ["slug"]),

  teams: defineTable({
    ownerId: v.string(), // Clerk ID de quem gerou
    characters: v.array(
      v.object({
        jikanId: v.number(),
