  }).index("by_date", ["generatedAt"]),

  promos: defineTable({
    title: v.string(),
    embed_url: v.string(),
    image_url: v.string(),
    updatedAt: v.number(),
  }).index("by_date", ["updatedAt"]),

  audit_logs: defineTable({
