const blogWelcomeChatBotComponent = `'use client';
import { useAction } from "convex/react";
import { api } from "@/convex/_generated/api";
import { useEffect, useState } from "react";
import { useUser } from "@clerk/nextjs";

export default function WelcomeChatBot() {
  const { user, isLoaded } = useUser();
  const generateWelcome = useAction(api.gemini.generateWelcomeMessage);
  const [hasPlayed, setHasPlayed] = useState(false);
  const [text, setText] = useState("");

  useEffect(() => {
    const playAudio = async () => {
      if (!isLoaded || !user || hasPlayed) return;

      try {
        const result = await generateWelcome({ userName: user.firstName || "Visitante" });
        if (result.text) setText(result.text);

        if (result.audioData) {
          // Decode Base64 to ArrayBuffer
          const binaryString = window.atob(result.audioData);
          const len = binaryString.length;
          const bytes = new Uint8Array(len);
          for (let i = 0; i < len; i++) {
            bytes[i] = binaryString.charCodeAt(i);
          }

          const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
          const audioBuffer = await audioContext.decodeAudioData(bytes.buffer);
          const source = audioContext.createBufferSource();
          source.buffer = audioBuffer;
          source.connect(audioContext.destination);
          source.start(0);
        }
        setHasPlayed(true);
      } catch (e) {
        console.error("TTS Error", e);
      }
    };

    if (user && !hasPlayed) {
        // Small delay to ensure page load
        const t = setTimeout(playAudio, 1000);
        return () => clearTimeout(t);
    }
  }, [user, isLoaded, hasPlayed, generateWelcome]);

