const blogWelcomeChatBotComponent = `'use client';
import { useEffect, useState, useRef } from 'react';
import { useUser } from '@clerk/nextjs';
import { useAction } from 'convex/react';
import { api } from '@/convex/_generated/api';

export default function WelcomeChatBot() {
  const { user, isSignedIn } = useUser();
  const generateWelcome = useAction(api.gemini.generateWelcomeMessage);
  const [message, setMessage] = useState<string>('');
  const [audioBase64, setAudioBase64] = useState<string | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);

  useEffect(() => {
    const fetchWelcome = async () => {
      if (isSignedIn && user && !message) {
        const name = user.firstName || user.username || 'User';
        try {
          const result = await generateWelcome({ userName: name });
          setMessage(result.text);
          setAudioBase64(result.audioData);
        } catch (error) { console.error(error); }
      }
    };
    fetchWelcome();
  }, [isSignedIn, user]);

  const playAudio = async () => {
    if (!audioBase64) return;
    setIsPlaying(true);

    try {
        // Decode raw PCM data
        const binaryString = atob(audioBase64);
        const len = binaryString.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
            bytes[i] = binaryString.charCodeAt(i);
        }

        const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

        // Int16 to Float32 conversion
        const dataInt16 = new Int16Array(bytes.buffer);
        const buffer = audioCtx.createBuffer(1, dataInt16.length, 24000);
        const channelData = buffer.getChannelData(0);
        for (let i = 0; i < dataInt16.length; i++) {
            channelData[i] = dataInt16[i] / 32768.0;
        }

        const source = audioCtx.createBufferSource();
        source.buffer = buffer;
        source.connect(audioCtx.destination);
        source.onended = () => setIsPlaying(false);
        source.start();

    } catch (e) {
        console.error("Audio play failed", e);
        setIsPlaying(false);
    }
  };

  if (!isSignedIn || !message) return null;

  return (
    <div style={{
        position: 'fixed', bottom: '20px', right: '20px', width: '300px',
        background: 'var(--card-bg)', border: '1px solid var(--border-color)',
        padding: '15px', boxShadow: '0 0 15px rgba(0,0,0,0.2)', zIndex: 999,
        borderRadius: '8px'
    }}>
      <div style={{ borderBottom: '1px solid var(--border-color)', marginBottom: '5px', fontWeight: 'bold', color: 'var(--color-accent)', display: 'flex', justifyContent: 'space-between' }}>
          <span>AI_MESSAGE</span>
          <span style={{fontSize: '0.7rem'}}>TTS_ACTIVE</span>
      </div>
      <p style={{ fontSize: '0.85rem', marginBottom: '10px' }}>{message}</p>

      {audioBase64 && (
          <button 
            onClick={playAudio} 
            disabled={isPlaying}
            className="btn"
            style={{ width: '100%', fontSize: '0.75rem', padding: '5px' }}
          >
            {isPlaying ? 'REPRODUZINDO...' : '🔊 REPRODUZIR ÁUDIO'}
          </button>
      )}
    </div>
  );
}`;

