const blogMatrixLoaderComponent = `'use client';
import { useEffect, useRef } from 'react';

export default function MatrixLoader() {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if(!canvas) return;
        const ctx = canvas.getContext('2d');
        if(!ctx) return;

        // Full screen
        const resize = () => {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        };
        window.addEventListener('resize', resize);
        resize();

        const letters = '010101010101ABCDEFGHIJKLMNOPQRSTUVWXYZ';
        const fontSize = 14;
        const columns = canvas.width / fontSize;
        const drops = Array(Math.ceil(columns)).fill(1);

        const draw = () => {
            // Black BG with opacity for trail effect
            ctx.fillStyle = 'rgba(0, 0, 0, 0.05)';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            ctx.fillStyle = '#0F0'; // Matrix Green (hardcoded for effect)
            ctx.font = \`\${fontSize}px monospace\`;

            for(let i=0; i<drops.length; i++) {
                const text = letters[Math.floor(Math.random()*letters.length)];
                ctx.fillText(text, i*fontSize, drops[i]*fontSize);

                if(drops[i]*fontSize > canvas.height && Math.random() > 0.975) {
                    drops[i] = 0;
                }
                drops[i]++;
            }
        };

        const interval = setInterval(draw, 33);
        return () => {
            clearInterval(interval);
            window.removeEventListener('resize', resize);
        };
    }, []);

    return (
        <div style={{ 
            position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', 
            zIndex: 9999, background: 'black', display: 'flex', alignItems: 'center', justifyContent: 'center' 
        }}>
            <canvas ref={canvasRef} style={{ display: 'block' }} />
            <h2 style={{ 
                position: 'absolute', color: 'white', background: 'black', padding: '10px', 
                border: '1px solid #0F0', borderRadius: '4px', fontFamily: 'monospace' 
            }}>
                ACCESSING MAINFRAME...
            </h2>
        </div>
    );
}
`;

const blogVibeMatcherComponent = `'use client';
import { useState } from 'react';
import { useAction } from 'convex/react';
import { api } from '@/convex/_generated/api';

export default function VibeMatcher() {
    const matchVibe = useAction(api.jikan.matchVibe);
    const [vibe, setVibe] = useState('');
    const [loading, setLoading] = useState(false);
    const [result, setResult] = useState<any>(null);

    const handleMatch = async () => {
        if(!vibe.trim()) return;
        setLoading(true);
        try {
            const data = await matchVibe({ vibe });
            setResult(data);
        } catch(e) {
            console.error(e);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="card" style={{ border: '1px solid var(--color-accent)' }}>
            <h2 style={{ fontSize: '1.1rem', color: 'var(--color-accent)', marginBottom: '15px' }}>
                >_ VIBE_MATCHER_AI
            </h2>
            <p style={{ fontSize: '0.9rem', color: 'var(--text-secondary)', marginBottom: '15px' }}>
                Tell the AI how you feel, and we'll find the anime for you.
            </p>

            <div style={{ display: 'flex', gap: '10px', marginBottom: '20px' }}>
                <input 
                    type="text" 
                    placeholder="Ex: Cyberpunk triste, Romance escolar..." 
                    value={vibe}
                    onChange={(e) => setVibe(e.target.value)}
                    style={{ 
                        flex: 1, padding: '10px', background: 'var(--bg-color)', 
                        border: '1px solid var(--border-color)', color: 'var(--text-primary)',
                        fontFamily: 'monospace'
                    }}
                    onKeyDown={(e) => e.key === 'Enter' && handleMatch()}
                />
                <button className="btn" onClick={handleMatch} disabled={loading}>
                    {loading ? 'SCANNING...' : 'ANALYZE'}
                </button>
            </div>

            {result && (
                <div style={{ borderTop: '1px solid var(--border-color)', paddingTop: '15px' }}>
                    <p style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', marginBottom: '10px' }}>
                        DETECTED KEYWORDS: <span style={{ color: 'var(--color-accent)' }}>[{result.keyword}]</span>
                    </p>

                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(100px, 1fr))', gap: '15px' }}>
                        {result.animes.map((anime: any) => (
                            <a 
                                key={anime.mal_id} 
                                href={anime.url} target="_blank" 
                                style={{ display: 'block', textAlign: 'center', border: 'none' }}
                            >
                                <img 
                                    src={anime.images.jpg.image_url} 
                                    style={{ width: '100%', borderRadius: '4px', marginBottom: '5px' }} 
                                />
