                if(data.quote) setQuote(data);
            })
            .catch(err => console.log("Quote fetch failed", err));
    }, []);

    if(!quote) return null;

    return (
        <div className="dev-quote">
            <p>"{quote.quote}"</p>
            <p style={{ marginTop: '5px', color: 'var(--color-accent)' }}>
                — {quote.character} ({quote.anime})
            </p>
        </div>
    );
}
`;

