  }).index("by_slug", ["slug"]),

  teams: defineTable({
    ownerId: v.string(), // Clerk ID de quem gerou
    characters: v.array(
      v.object({
        jikanId: v.number(),
        name: v.string(),
        imageUrl: v.string(),
      })
    ),
    createdAt: v.number(),
  }).index("by_owner", ["ownerId"]),

  games: defineTable({
    title: v.string(),
    thumbnail: v.string(),
    platform: v.string(),
