                <div style={{ fontSize: '0.9rem', color: 'var(--text-secondary)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <span>Por Kira (AI) | {new Date(post.published_date).toLocaleDateString()}</span>

