const blogConvexGeminiContent = `import { action } from "./_generated/server";
import { v } from "convex/values";
import { GoogleGenAI } from "@google/genai";

export const chat = action({
  args: { message: v.string() },
  handler: async (ctx, { message }) => {
    const apiKey = process.env.GEMINI_API_KEY;
    if (!apiKey) return "Erro de Configuração: API Key ausente.";

    const ai = new GoogleGenAI({ apiKey });

    try {
        const response = await ai.models.generateContent({
            model: "gemini-2.5-flash",
            contents: \`Atue como uma IA assistente de um blog Tech/Otaku chamado 'Terminal Blog'. 
            Seja breve, amigável e use gírias leves de internet/dev.
            Responda à mensagem do usuário: "\${message}"\`
        });
        return response.text;
    } catch (e) {
        return "Erro ao processar mensagem.";
    }
  }
});
`;

