                            <div className={styles.reviewHeader}>
                                <span className={styles.reviewerName}>{r.userName}</span>
                                <div className={styles.stars}>{[...Array(5)].map((_, i) => <Star key={i} size={14} fill={i < r.rating ? "#fff" : "none"} stroke="#fff"/>)}</div>
